def subtract(a, b):
    # Filter out empty intervals and sort by start point
    a_valid = sorted([interval for interval in a if interval[0] < interval[1]])
    b_valid = sorted([interval for interval in b if interval[0] < interval[1]])

    # Merge overlapping intervals in b
    b_merged = []
    for start, end in b_valid:
        if b_merged and start <= b_merged[-1][1]:
            # Overlapping or touching, merge
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            # Non-overlapping, add new interval
            b_merged.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in a_valid:
        current_intervals = [[a_start, a_end]]

        # Subtract each merged b interval from current intervals
        for b_start, b_end in b_merged:
            new_intervals = []
            for c_start, c_end in current_intervals:
                # No overlap
                if c_end <= b_start or c_start >= b_end:
                    new_intervals.append([c_start, c_end])
                else:
                    # There is overlap, keep the parts not covered by b
                    if c_start < b_start:
                        new_intervals.append([c_start, b_start])
                    if c_end > b_end:
                        new_intervals.append([b_end, c_end])
            current_intervals = new_intervals

        result.extend(current_intervals)

    # Sort result and merge touching intervals
    result.sort()
    merged_result = []
    for start, end in result:
        if merged_result and start <= merged_result[-1][1]:
            # Touching or overlapping, merge
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

